reversal.fixed_text:
// Check if the last codepoint is a line break.
match &text[i..] {
    "\u{000A}" | "\u{000B}" | "\u{000C}" | "\u{000D}" | "\u{0085}" | "\u{2028}"
    | "\u{2029}" => true,
    _ => false,
}

reversal.parent_text:
// Check if the last codepoint is a line break.
match &text[i..] {
    "u{000A}" | "u{000B}" | "u{000C}" | "u{000D}" | "u{0085}" | "u{2028}" | "u{2029}" => true,
    _ => false,
}
